/**
 * Shared helpers for native-like form control custom elements.
 */

/**
 * @param {HTMLElement} host
 * @param {string} name
 * @param {string | number | null | undefined} value
 * @returns {string}
 */
export function reflectStringAttr(host, name, value) {
    const next = value == null || value === '' ? '' : String(value);
    if (next === '') {
        if (host.hasAttribute(name)) host.removeAttribute(name);
    } else if (host.getAttribute(name) !== next) {
        host.setAttribute(name, next);
    }
    return next;
}

/**
 * @param {HTMLElement} host
 * @param {string} name
 * @param {unknown} value
 * @returns {boolean}
 */
export function reflectBoolAttr(host, name, value) {
    const next = !!value;
    if (host.hasAttribute(name) !== next) {
        if (next) host.setAttribute(name, '');
        else host.removeAttribute(name);
    }
    return next;
}

/**
 * @param {HTMLElement} host
 * @param {string} name
 * @param {() => unknown} get
 */
export function defineReadonlyProperty(host, name, get) {
    Object.defineProperty(host, name, {
        configurable: true,
        enumerable: true,
        get,
    });
}

/**
 * @param {HTMLElement} host
 * @param {string} name
 * @param {() => unknown} get
 * @param {(value: unknown) => void} set
 */
export function defineWritableProperty(host, name, get, set) {
    Object.defineProperty(host, name, {
        configurable: true,
        enumerable: true,
        get,
        set,
    });
}

/**
 * @param {HTMLElement} host
 * @param {Record<string, any>} state
 * @param {string} name
 * @param {() => void} [afterSet]
 */
export function defineStringProperty(host, state, name, afterSet = () => {}) {
    defineWritableProperty(
        host,
        name,
        () => state[name],
        (value) => {
            state[name] = reflectStringAttr(host, name, /** @type {any} */ (value));
            afterSet();
        },
    );
}

/**
 * @param {HTMLElement} host
 * @param {Record<string, any>} state
 * @param {string} propName
 * @param {string} attrName
 * @param {() => void} [afterSet]
 */
export function defineBooleanProperty(host, state, propName, attrName, afterSet = () => {}) {
    defineWritableProperty(
        host,
        propName,
        () => !!state[attrName],
        (value) => {
            state[attrName] = reflectBoolAttr(host, attrName, value);
            afterSet();
        },
    );
}

/**
 * @param {HTMLElement} host
 * @param {{
 *   focusTarget: HTMLInputElement,
 *   willValidate: () => boolean,
 *   stepBy: (amount: number) => void,
 * }} options
 */
export function defineFormControlApi(host, { focusTarget, willValidate, stepBy }) {
    defineReadonlyProperty(host, 'willValidate', willValidate);

    /** @type {any} */ (host).focus = (/** @type {FocusOptions} */ options) => focusTarget.focus(options);
    /** @type {any} */ (host).blur = () => focusTarget.blur();
    /** @type {any} */ (host).select = () => focusTarget.select();
    /** @type {any} */ (host).stepUp = (n = 1) => stepBy(Number(n));
    /** @type {any} */ (host).stepDown = (n = 1) => stepBy(-Number(n));
}

web-components/src/icon.jsx.content:
/**
 * @import { IconDef } from '@neon-kit/icons'
 */
import {
    attributes,
    defineElement,
    internals,
    props,
    stringAttribute,
    withInternals,
} from '@slimlib/element';
import { effect, signal } from '@slimlib/store';
import { SvgIcon } from './svg-icon.jsx';

/**
 * Public instance type of the `<neon-icon>` element.
 *
 * @typedef {HTMLElement & {
 *   name: string,
 *   label: string,
 *   icon: IconDef | undefined,
 * }} NeonIconElement
 */
defineElement(
    'neon-icon',
    [
        withInternals(),
        attributes({
            label: stringAttribute,
            name: stringAttribute,
        }),
    ],
    () => {
        const elementInternals = internals();
        const state = props({
            name: undefined,
            label: null,
            icon: /** @type {IconDef | undefined} */ (undefined),
        });

        /** @type {import('@slimlib/store').Signal<IconDef | undefined>} */
        const loadedIconDef = signal(/** @type {IconDef | undefined} */ (undefined));

        effect(() => {
            const override = state.icon;
            const name = state.name;
            if (override || !name) {
                loadedIconDef.set(undefined);
                return;
            }
            import(/* @vite-ignore */ `@neon-kit/icons/${name}`).then(
                (mod) => {
                    if (name === state.name) {
                        loadedIconDef.set(mod.default);
                    }
                },
                () => {
                    if (name === state.name) {
                        loadedIconDef.set(undefined);
                    }
                },
            );
        });

        effect(() => {
            const label = state.label;
            elementInternals.ariaLabel = label;
            elementInternals.ariaHidden = label ? null : 'true';
            elementInternals.role = label ? 'img' : null;
        });

        return () => {
            const def = state.icon || loadedIconDef();
            return def ? SvgIcon(def) : null;
        };
    },
);

