/**
 * @typedef {number} FocusableFlags
 */
export const FOCUSABLE_PROGRAMMATIC = 1;

/**
 * @param {string} name
 */
export function generateId(name) {
    return `${name}-${Math.random().toString(36).slice(2, 11)}`;
}

/**
 * @param {Element} element
 */
export function getActiveElement(element) {
    const root = element.getRootNode();
    return root instanceof ShadowRoot ? root.activeElement : element.ownerDocument.activeElement;
}

/**
 * @param {Element} element
 */
export function isDisabled(element) {
    return element.hasAttribute('disabled') || element.getAttribute('aria-disabled') === 'true';
}

/**
 * @param {Element} element
 * @param {FocusableFlags} [flags]
 */
export function isFocusable(element, flags = 0) {
    const maybeDisabled = /** @type {Element & { disabled?: boolean }} */ (element);
    const disabled = maybeDisabled.disabled === true;
    const tabindex = element.getAttribute('tabindex');
    const allowsProgrammaticFocus = (flags & FOCUSABLE_PROGRAMMATIC) === FOCUSABLE_PROGRAMMATIC;
    const isKeyboardDisabled = !allowsProgrammaticFocus && tabindex === '-1';
    return !disabled
        && !isKeyboardDisabled
        && element.closest('[inert]') === null
        && !element.matches('input[type="hidden" i]')
        && (tabindex !== null
            || element.matches('button, a[href], area[href], input, select, textarea, summary, iframe, audio[controls], video[controls], [contenteditable=""], [contenteditable="true"]'));
}

site/combobox.js.content:
/* Combobox demo behavior — used only by the docs site to make the
   single- and multi-select layouts interactive. This is NOT a shipped
   library; it lives in the docs because the section fragments are
   injected via innerHTML and per-fragment <script> tags don't run.

   Behaviors (single):
     - Click field (or Space/Enter while focused) toggles popover.
     - Clicking an option sets the value and closes.
     - Optional clear button removes the value (also clicks-through to
       avoid opening the popover).
     - Optional search filter narrows visible options live.
     - Optional create button appends a new option from the typed query.

   Behaviors (multi):
     - Field acts as a focus container for the inline input.
     - Options rendered with .checkbox; clicking toggles a tag in the
       field. Tag's × removes the corresponding tag.
     - Optional search filter narrows visible options.
     - Optional select-all toggles every visible option (indeterminate
       when partially selected).
     - Optional create-new appends a tag from the typed query.
     - Pressing Enter in the inline input creates (when creatable) or
       selects the first match.
     - Pressing Backspace in an empty input removes the last tag.

   Boots once on DOMContentLoaded and re-boots whenever the docs router
   swaps the inner fragment (observes #content-inner mutations).
*/

(() => {
    const REMOVE_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M6 6l12 12M18 6L6 18"/></svg>`;
    const CHECK_SVG = `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2.5" stroke="currentColor" class="combobox__option-check" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m4.5 12.75 6 6 9-13.5"/></svg>`;

    const parseList = (raw, fallback = []) => {
        if (!raw) return fallback;
        try { return JSON.parse(raw); } catch { return fallback; }
    };

    const escapeHtml = (s) =>
        String(s).replace(/[&<>"']/g, (c) => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        })[c]);

    /* --------------------------- single-select --------------------------- */

    const initSingle = (root) => {
        if (root.dataset.cbInit) return;
        root.dataset.cbInit = '1';

        const field = root.querySelector('.combobox__field');
        const valueEl = root.querySelector('[data-cb-value]');
        const placeholderEl = root.querySelector('[data-cb-placeholder]');
        const clearEl = root.querySelector('[data-cb-clear]');
        const popover = root.querySelector('[data-cb-popover]');
        const list = root.querySelector('[data-cb-list]');
        const searchEl = root.querySelector('[data-cb-search]');
        const footer = root.querySelector('[data-cb-footer]');
        const createBtn = root.querySelector('[data-cb-create]');
        const createLabel = root.querySelector('[data-cb-create-label]');

        const state = {
            options: parseList(root.dataset.options, []),
            value: root.dataset.value || null,
            query: '',
        };

        const setValue = (v) => {
            state.value = v;
            if (v == null) {
                if (valueEl) { valueEl.textContent = ''; valueEl.hidden = true; }
                if (placeholderEl) placeholderEl.hidden = false;
                if (clearEl) clearEl.hidden = true;
            } else {
                if (valueEl) { valueEl.textContent = v; valueEl.hidden = false; }
                if (placeholderEl) placeholderEl.hidden = true;
                if (clearEl) clearEl.hidden = false;
            }
            renderList();
        };

        const renderList = () => {
            const q = state.query.trim().toLowerCase();
            const matches = state.options.filter((o) =>
                !q || o.toLowerCase().includes(q),
            );
            if (matches.length === 0) {
                list.innerHTML = `<div class="combobox__empty">No results</div>`;
            } else {
                list.innerHTML = matches.map((o) => `
                    <button class="combobox__option" type="button" role="option"
                            data-cb-pick="${escapeHtml(o)}"
                            aria-selected="${o === state.value ? 'true' : 'false'}">
                        <span></span>
                        <span class="combobox__option-label">${escapeHtml(o)}</span>
                        ${CHECK_SVG}
                    </button>
                `).join('');
            }

            if (footer && createBtn) {
                const trimmed = state.query.trim();
                const exists = state.options.some(
                    (o) => o.toLowerCase() === trimmed.toLowerCase(),
                );
                const show = trimmed.length > 0 && !exists;
                footer.hidden = !show;
                if (show && createLabel) {
                    createLabel.textContent = `Create "${trimmed}"`;
                }
            }
        };

        // Open / close — sync aria-expanded with popover toggle events.
        if (popover && field) {
            popover.addEventListener('toggle', (e) => {
                field.setAttribute('aria-expanded', e.newState === 'open' ? 'true' : 'false');
                if (e.newState === 'open') {
                    state.query = '';
                    if (searchEl) { searchEl.value = ''; searchEl.focus(); }
                    renderList();
                }
            });
        }

        // Clear button — stop click from re-opening / submitting field.
        if (clearEl) {
            const clear = (e) => {
                e.preventDefault();
                e.stopPropagation();
                setValue(null);
            };
            clearEl.addEventListener('click', clear);
            clearEl.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') clear(e);
            });
        }

        // Pick option.
        list.addEventListener('click', (e) => {
            const btn = e.target.closest('[data-cb-pick]');
            if (!btn) return;
            setValue(btn.dataset.cbPick);
            if (popover && popover.matches(':popover-open')) popover.hidePopover();
        });

        // Search filter.
        if (searchEl) {
            searchEl.addEventListener('input', () => {
                state.query = searchEl.value;
                renderList();
            });
        }

        // Create new.
        if (createBtn) {
            createBtn.addEventListener('click', () => {
                const v = state.query.trim();
                if (!v) return;
                if (!state.options.includes(v)) state.options.push(v);
                setValue(v);
                if (popover && popover.matches(':popover-open')) popover.hidePopover();
            });
        }

        setValue(state.value);
    };

    /* ---------------------------- multi-select --------------------------- */

    const initMulti = (root) => {
        if (root.dataset.cbInit) return;
        root.dataset.cbInit = '1';

        const field = root.querySelector('[data-cb-field]');
        const valuesEl = root.querySelector('[data-cb-values]');
        const inputEl = root.querySelector('[data-cb-input]');
        const popover = root.querySelector('[data-cb-popover]');
        const list = root.querySelector('[data-cb-list]');
        const searchEl = root.querySelector('[data-cb-search]');
        const footer = root.querySelector('[data-cb-footer]');
        const createBtn = root.querySelector('[data-cb-create]');
        const createLabel = root.querySelector('[data-cb-create-label]');
        const selectAllRow = root.querySelector('[data-cb-select-all]');
        const selectAllInput = root.querySelector('[data-cb-select-all-input]');
        const creatable = root.hasAttribute('data-creatable');

        // Wire an explicit anchor between the visible field and the
        // popover. The chevron-button has `popovertarget`, so its
        // implicit anchor would be only the tiny chevron; we want the
        // popover to track the whole field. Also, the inline `<input>`
        // calls `popover.showPopover()` programmatically when the user
        // types, and programmatic opens drop the implicit anchor
        // entirely \u2014 the explicit `position-anchor` survives both
        // invocation paths.
        if (popover && popover.id && field) {
            const name = `--cb-anchor-${popover.id.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
            field.style.anchorName = name;
            popover.style.positionAnchor = name;
        }

        const state = {
            options: parseList(root.dataset.options, []),
            value: parseList(root.dataset.value, []),
            query: '',
        };

        const renderTags = () => {
            valuesEl.innerHTML = state.value.map((v) => `
                <span class="tag">
                    ${escapeHtml(v)}
                    <button type="button" class="tag__remove" data-cb-remove="${escapeHtml(v)}" aria-label="Remove ${escapeHtml(v)}">
                        ${REMOVE_SVG}
                    </button>
                </span>
            `).join('');
        };

        const renderList = () => {
            const q = state.query.trim().toLowerCase();
            const matches = state.options.filter((o) =>
                !q || o.toLowerCase().includes(q),
            );
            if (matches.length === 0) {
                list.innerHTML = `<div class="combobox__empty">No results</div>`;
            } else {
                list.innerHTML = matches.map((o) => `
                    <label class="combobox__option" data-cb-toggle="${escapeHtml(o)}">
                        <input type="checkbox" class="checkbox" ${state.value.includes(o) ? 'checked' : ''} tabindex="-1">
                        <span class="combobox__option-label">${escapeHtml(o)}</span>
                    </label>
                `).join('');
            }

            // Select-all indeterminate / checked sync.
            if (selectAllInput) {
                const visibleSelected = matches.filter((m) => state.value.includes(m)).length;
                selectAllInput.checked = matches.length > 0 && visibleSelected === matches.length;
                selectAllInput.indeterminate =
                    visibleSelected > 0 && visibleSelected < matches.length;
            }

            if (footer && createBtn && creatable) {
                const trimmed = state.query.trim();
                const exists = state.options.some(
                    (o) => o.toLowerCase() === trimmed.toLowerCase(),
                );
                const show = trimmed.length > 0 && !exists;
                footer.hidden = !show;
                if (show && createLabel) {
                    createLabel.textContent = `Create "${trimmed}"`;
                }
            }
        };

        const toggle = (v) => {
            const idx = state.value.indexOf(v);
            if (idx === -1) state.value.push(v);
            else state.value.splice(idx, 1);
            renderTags();
            renderList();
        };

        const remove = (v) => {
            state.value = state.value.filter((x) => x !== v);
            renderTags();
            renderList();
        };

        const create = (raw) => {
            const v = raw.trim();
            if (!v) return;
            if (!state.options.includes(v)) state.options.push(v);
            if (!state.value.includes(v)) state.value.push(v);
            renderTags();
            renderList();
        };

        // Field click focuses inline input — feels like a textarea.
        field.addEventListener('mousedown', (e) => {
            if (e.target.closest('.tag__remove, .combobox__chevron-btn, .tag')) return;
            // Defer so the click doesn't steal focus from popover triggers.
            queueMicrotask(() => inputEl.focus());
        });

        // Open / close.
        if (popover) {
            popover.addEventListener('toggle', (e) => {
                if (e.newState === 'open') {
                    root.setAttribute('data-open', '');
                    state.query = inputEl.value || '';
                    if (searchEl) { searchEl.value = state.query; }
                    renderList();
                    (searchEl || inputEl).focus();
                } else {
                    root.removeAttribute('data-open');
                }
            });
        }

        // Tag remove.
        valuesEl.addEventListener('click', (e) => {
            const btn = e.target.closest('[data-cb-remove]');
            if (!btn) return;
            e.preventDefault();
            e.stopPropagation();
            remove(btn.dataset.cbRemove);
        });

        // Option toggle. Uses click on the label; suppress the implicit
        // checkbox click so we control the checked state.
        list.addEventListener('click', (e) => {
            const row = e.target.closest('[data-cb-toggle]');
            if (!row) return;
            e.preventDefault();
            toggle(row.dataset.cbToggle);
        });

        // Search filter (popover-side).
        if (searchEl) {
            searchEl.addEventListener('input', () => {
                state.query = searchEl.value;
                if (inputEl) inputEl.value = state.query;
                renderList();
            });
        }

        // Inline input — type-to-filter; Enter creates or picks first
        // match; Backspace on empty removes last tag.
        inputEl.addEventListener('input', () => {
            state.query = inputEl.value;
            if (searchEl) searchEl.value = state.query;
            renderList();
            if (popover && !popover.matches(':popover-open')) {
                try { popover.showPopover(); } catch { /* unsupported */ }
            }
        });

        inputEl.addEventListener('keydown', (e) => {
            if (e.key === 'Backspace' && inputEl.value === '' && state.value.length) {
                e.preventDefault();
                remove(state.value[state.value.length - 1]);
                return;
            }
            if (e.key === 'Enter') {
                e.preventDefault();
                const q = inputEl.value.trim();
                if (!q) return;
                const match = state.options.find((o) => o.toLowerCase() === q.toLowerCase());
                if (match) {
                    if (!state.value.includes(match)) toggle(match);
                } else if (creatable) {
                    create(q);
                }
                inputEl.value = '';
                state.query = '';
                if (searchEl) searchEl.value = '';
                renderList();
            }
            if (e.key === 'Escape' && popover && popover.matches(':popover-open')) {
                popover.hidePopover();
            }
        });

        // Create new (footer button).
        if (createBtn) {
            createBtn.addEventListener('click', () => {
                create(state.query);
                inputEl.value = '';
                state.query = '';
                if (searchEl) searchEl.value = '';
                renderList();
            });
        }

        // Select all toggle — operates on currently visible (filtered) options.
        if (selectAllRow) {
            selectAllRow.addEventListener('click', (e) => {
                e.preventDefault();
                const q = state.query.trim().toLowerCase();
                const visible = state.options.filter((o) =>
                    !q || o.toLowerCase().includes(q),
                );
                const allSelected = visible.length > 0 && visible.every((v) => state.value.includes(v));
                if (allSelected) {
                    state.value = state.value.filter((v) => !visible.includes(v));
                } else {
                    for (const v of visible) {
                        if (!state.value.includes(v)) state.value.push(v);
                    }
                }
                renderTags();
                renderList();
            });
        }

        renderTags();
        renderList();
    };

    const boot = (root = document) => {
        for (const el of root.querySelectorAll('[data-combobox="single"]')) initSingle(el);
        for (const el of root.querySelectorAll('[data-combobox="multi"]')) initMulti(el);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => boot(), { once: true });
    } else {
        boot();
    }

    // Re-boot on docs-router fragment swap.
    const inner = document.getElementById('content-inner');
    if (inner) {
        const observer = new MutationObserver(() => boot(inner));
        observer.observe(inner, { childList: true, subtree: true });
    }
})();

site/datepicker.js.content:
/* Datepicker demo behavior — minimal implementation used only by the
   docs site to make the field/popover layouts interactive. NOT a
   shipped library. Behavior:
     - Typed input parses YYYY-MM-DD; invalid input is left as-is.
     - Calendar trigger opens the popover, which renders one of three
       views: days (in a month), months (in a year), years (in a 12-year
       window with a leading and trailing pad).
     - Clicking the view-switch label cycles days → months → years.
     - Clicking the prev/next chevrons walks one unit (month / year /
       decade) at a time.
     - Clicking a cell in the days view commits the date and closes the
       popover; in months/years it drills back down toward days.
     - Optional clear button blanks the value.
     - Cells render with arrow-key roving-tabindex for keyboard nav.
*/

(() => {
    const ICON_PREV = `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5"/></svg>`;
    const ICON_NEXT = `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="currentColor" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="m8.25 4.5 7.5 7.5-7.5 7.5"/></svg>`;

    const MONTH_LONG = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    const MONTH_SHORT = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const WEEKDAY_SHORT = ['Mo','Tu','We','Th','Fr','Sa','Su'];

    const pad2 = (n) => String(n).padStart(2, '0');
    const fmtISO = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
    const parseISO = (s) => {
        const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec((s || '').trim());
        if (!m) return null;
        const d = new Date(+m[1], +m[2] - 1, +m[3]);
        return Number.isNaN(d.getTime()) ? null : d;
    };
    const sameDay = (a, b) => a && b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
    const dayTime = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
    const cmpDay = (a, b) => dayTime(a) - dayTime(b);

    const init = (root) => {
        if (root.dataset.dpInit) return;
        root.dataset.dpInit = '1';

        const input = root.querySelector('[data-dp-input]');
        const clearBtn = root.querySelector('[data-dp-clear]');
        const popover = root.querySelector('[data-dp-popover]');
        const clearable = root.hasAttribute('data-clearable');
        const range = root.hasAttribute('data-range');

        // Anchor the popover to the visible field rather than to the
        // calendar-icon trigger button. Without this, `popovertarget`'s
        // implicit anchor is the tiny icon button, so the popover lands
        // hugging the right edge of the field instead of below it.
        const field = root.querySelector('.datepicker__field');
        if (popover && popover.id && field) {
            const name = `--dp-anchor-${popover.id.replace(/[^a-zA-Z0-9_-]/g, '_')}`;
            field.style.anchorName = name;
            popover.style.positionAnchor = name;
        }

        // Parse initial value. Range mode accepts "YYYY-MM-DD/YYYY-MM-DD".
        const rawInitial = (root.dataset.value || input?.value || '').trim();
        let initialStart = null, initialEnd = null;
        if (range) {
            const parts = rawInitial.split(/\s*\/\s*/);
            initialStart = parseISO(parts[0]);
            initialEnd = parseISO(parts[1]);
            if (initialStart && initialEnd && cmpDay(initialStart, initialEnd) > 0) {
                [initialStart, initialEnd] = [initialEnd, initialStart];
            }
        } else {
            initialStart = parseISO(rawInitial);
        }

        const today = new Date();
        const state = {
            view: 'days',          // days | months | years
            cursor: initialStart
                ? new Date(initialStart.getFullYear(), initialStart.getMonth(), 1)
                : new Date(today.getFullYear(), today.getMonth(), 1),
            selected: range ? null : initialStart,
            // Range state — start/end are the committed endpoints; hovered
            // tracks the cursor while the user is picking the second one.
            start: range ? initialStart : null,
            end: range ? initialEnd : null,
            hovered: null,
        };

        const formatRange = () => {
            if (state.start && state.end) return `${fmtISO(state.start)} / ${fmtISO(state.end)}`;
            if (state.start) return `${fmtISO(state.start)} / `;
            return '';
        };

        if (input) {
            if (range) input.value = formatRange();
            else if (initialStart) input.value = fmtISO(initialStart);
        }
        if (range && state.start && !state.end) root.classList.add('-range-pending');

        const updateClear = () => {
            if (!clearBtn) return;
            clearBtn.hidden = !(clearable && input && input.value.trim());
        };
        updateClear();

        const setSelected = (d) => {
            state.selected = d ? new Date(d) : null;
            if (input) input.value = d ? fmtISO(d) : '';
            updateClear();
        };

        const setRange = (s, e) => {
            state.start = s ? new Date(s) : null;
            state.end = e ? new Date(e) : null;
            state.hovered = null;
            if (input) input.value = formatRange();
            updateClear();
            // Wrapper flag drives the "pending" CSS — softer in-range band
            // and a dashed-outline trailing endpoint while we wait for the
            // user to commit the second click.
            root.classList.toggle('-range-pending', !!(state.start && !state.end));
        };

        // ----------------------------------------------------------------
        // Render
        // ----------------------------------------------------------------

        const navHeader = (label) => `
            <header class="datepicker__nav">
                <button class="datepicker__nav-btn" type="button" data-dir="prev" data-dp-prev aria-label="Previous">${ICON_PREV}</button>
                <button class="datepicker__view-switch" type="button" data-dp-switch>${label}</button>
                <button class="datepicker__nav-btn" type="button" data-dir="next" data-dp-next aria-label="Next">${ICON_NEXT}</button>
            </header>
        `;

        const renderDays = () => {
            const year = state.cursor.getFullYear();
            const month = state.cursor.getMonth();
            const first = new Date(year, month, 1);
            const startWeekday = (first.getDay() + 6) % 7; // Mon-first
            const daysInMonth = new Date(year, month + 1, 0).getDate();
            const cells = [];
            // Weekday header
            for (const w of WEEKDAY_SHORT) cells.push(`<div class="datepicker__weekday">${w}</div>`);
            // Leading pad
            for (let i = startWeekday; i > 0; i--) {
                const d = new Date(year, month, 1 - i);
                cells.push(cellHtml(d, true));
            }
            for (let day = 1; day <= daysInMonth; day++) {
                cells.push(cellHtml(new Date(year, month, day), false));
            }
            // Trailing pad — fill grid to multiple of 7
            const total = startWeekday + daysInMonth;
            const trail = (7 - (total % 7)) % 7;
            for (let i = 1; i <= trail; i++) {
                cells.push(cellHtml(new Date(year, month + 1, i), true));
            }
            return navHeader(`${MONTH_LONG[month]} ${year}`) +
                `<div class="datepicker__grid -days">${cells.join('')}</div>`;
        };

        const cellHtml = (date, muted) => {
            const isToday = sameDay(date, today);
            const cls = ['datepicker__cell'];
            if (muted) cls.push('-muted');
            if (isToday) cls.push('-today');

            let pressed = false;
            if (range) {
                // Use the hovered date as a tentative end while picking.
                const tentativeEnd = state.end || (state.start && state.hovered) || null;
                const lo = state.start && tentativeEnd && cmpDay(state.start, tentativeEnd) <= 0 ? state.start : tentativeEnd;
                const hi = state.start && tentativeEnd && cmpDay(state.start, tentativeEnd) <= 0 ? tentativeEnd : state.start;
                const isStart = sameDay(date, state.start);
                const isEnd = !!tentativeEnd && sameDay(date, tentativeEnd);
                if (isStart) cls.push('-range-start');
                if (isEnd) cls.push('-range-end');
                if (lo && hi && cmpDay(date, lo) > 0 && cmpDay(date, hi) < 0) cls.push('-in-range');
                pressed = isStart || isEnd;
            } else {
                const isSelected = sameDay(date, state.selected);
                if (isSelected) cls.push('-selected');
                pressed = isSelected;
            }
            return `<button class="${cls.join(' ')}" type="button" data-dp-pick-day="${fmtISO(date)}"${pressed ? ' aria-pressed="true"' : ''}>${date.getDate()}</button>`;
        };

        const renderMonths = () => {
            const year = state.cursor.getFullYear();
            // In range mode highlight the months containing either endpoint;
            // in single mode keep the existing selected-month indicator.
            const monthHasMark = (i) => {
                if (range) {
                    const hits = [state.start, state.end].filter(Boolean);
                    return hits.some((d) => d.getFullYear() === year && d.getMonth() === i);
                }
                return state.selected
                    && state.selected.getFullYear() === year
                    && state.selected.getMonth() === i;
            };
            const cells = MONTH_SHORT.map((label, i) => {
                const isCurrent = today.getFullYear() === year && today.getMonth() === i;
                const isSelected = monthHasMark(i);
                const cls = [
                    'datepicker__cell',
                    isCurrent && '-today',
                    isSelected && '-selected',
                ].filter(Boolean).join(' ');
                return `<button class="${cls}" type="button" data-dp-pick-month="${i}"${isSelected ? ' aria-pressed="true"' : ''}>${label}</button>`;
            }).join('');
            return navHeader(String(year)) +
                `<div class="datepicker__grid -months">${cells}</div>`;
        };

        const renderYears = () => {
            const year = state.cursor.getFullYear();
            const start = year - (year % 12) - 1; // pad with one leading + two trailing
            const yearHasMark = (y) => {
                if (range) {
                    const hits = [state.start, state.end].filter(Boolean);
                    return hits.some((d) => d.getFullYear() === y);
                }
                return state.selected && state.selected.getFullYear() === y;
            };
            const cells = [];
            for (let i = 0; i < 16; i++) {
                const y = start + i;
                const muted = i === 0 || i > 12;
                const isCurrent = today.getFullYear() === y;
                const isSelected = yearHasMark(y);
                const cls = [
                    'datepicker__cell',
                    muted && '-muted',
                    isCurrent && '-today',
                    isSelected && '-selected',
                ].filter(Boolean).join(' ');
                cells.push(`<button class="${cls}" type="button" data-dp-pick-year="${y}"${isSelected ? ' aria-pressed="true"' : ''}>${y}</button>`);
            }
            const decadeLabel = `${start + 1} – ${start + 12}`;
            return navHeader(decadeLabel) +
                `<div class="datepicker__grid -years">${cells.join('')}</div>`;
        };

        const render = () => {
            popover.innerHTML =
                state.view === 'days' ? renderDays() :
                state.view === 'months' ? renderMonths() :
                renderYears();
        };

        // ----------------------------------------------------------------
        // Behavior
        // ----------------------------------------------------------------

        if (popover) {
            popover.addEventListener('toggle', (e) => {
                if (e.newState !== 'open') return;
                // Reset to days view + cursor on the selected (or current) month.
                state.view = 'days';
                const anchor = range
                    ? (state.start || state.end)
                    : state.selected;
                state.cursor = anchor
                    ? new Date(anchor.getFullYear(), anchor.getMonth(), 1)
                    : new Date(today.getFullYear(), today.getMonth(), 1);
                state.hovered = null;
                render();
            });

            popover.addEventListener('click', (e) => {
                const t = e.target;
                if (t.closest('[data-dp-prev]')) {
                    if (state.view === 'days') state.cursor = new Date(state.cursor.getFullYear(), state.cursor.getMonth() - 1, 1);
                    else if (state.view === 'months') state.cursor = new Date(state.cursor.getFullYear() - 1, state.cursor.getMonth(), 1);
                    else state.cursor = new Date(state.cursor.getFullYear() - 12, state.cursor.getMonth(), 1);
                    render();
                    return;
                }
                if (t.closest('[data-dp-next]')) {
                    if (state.view === 'days') state.cursor = new Date(state.cursor.getFullYear(), state.cursor.getMonth() + 1, 1);
                    else if (state.view === 'months') state.cursor = new Date(state.cursor.getFullYear() + 1, state.cursor.getMonth(), 1);
                    else state.cursor = new Date(state.cursor.getFullYear() + 12, state.cursor.getMonth(), 1);
                    render();
                    return;
                }
                if (t.closest('[data-dp-switch]')) {
                    state.view = state.view === 'days' ? 'months' : state.view === 'months' ? 'years' : 'days';
                    render();
                    return;
                }
                const dayBtn = t.closest('[data-dp-pick-day]');
                if (dayBtn) {
                    const d = parseISO(dayBtn.dataset.dpPickDay);
                    if (!d) return;
                    if (range) {
                        // First click (or restart after a complete range):
                        // arm the start endpoint and wait for a second click.
                        if (!state.start || (state.start && state.end)) {
                            setRange(d, null);
                            render();
                            return;
                        }
                        // Second click commits the range. Normalize order so
                        // start <= end regardless of which side was picked.
                        let s = state.start, e = d;
                        if (cmpDay(s, e) > 0) [s, e] = [e, s];
                        setRange(s, e);
                        popover.hidePopover();
                        return;
                    }
                    setSelected(d);
                    popover.hidePopover();
                    return;
                }
                const monthBtn = t.closest('[data-dp-pick-month]');
                if (monthBtn) {
                    state.cursor = new Date(state.cursor.getFullYear(), +monthBtn.dataset.dpPickMonth, 1);
                    state.view = 'days';
                    render();
                    return;
                }
                const yearBtn = t.closest('[data-dp-pick-year]');
                if (yearBtn) {
                    state.cursor = new Date(+yearBtn.dataset.dpPickYear, state.cursor.getMonth(), 1);
                    state.view = 'months';
                    render();
                    return;
                }
            });

            // While picking the second endpoint, follow the cursor so the
            // tentative band updates live. Cheap full re-render — there are
            // at most 42 cells.
            popover.addEventListener('mouseover', (e) => {
                if (!range) return;
                if (!state.start || state.end) return;
                const cell = e.target.closest('[data-dp-pick-day]');
                if (!cell) return;
                const d = parseISO(cell.dataset.dpPickDay);
                if (!d || sameDay(d, state.hovered)) return;
                state.hovered = d;
                render();
            });
            popover.addEventListener('mouseleave', () => {
                if (!range) return;
                if (state.hovered) { state.hovered = null; render(); }
            });

            // Arrow-key navigation between cells inside any grid view.
            popover.addEventListener('keydown', (e) => {
                const cell = e.target.closest('.datepicker__cell');
                if (!cell) return;
                const grid = cell.parentElement;
                const cells = [...grid.querySelectorAll('.datepicker__cell')];
                const idx = cells.indexOf(cell);
                if (idx === -1) return;
                const cols = grid.classList.contains('-days') ? 7 : 4;
                let next = idx;
                const isRtl = getComputedStyle(grid).direction === 'rtl';
                const left = isRtl ? 1 : -1;
                const right = -left;
                switch (e.key) {
                    case 'ArrowLeft':  next = idx + left;  break;
                    case 'ArrowRight': next = idx + right; break;
                    case 'ArrowUp':    next = idx - cols;  break;
                    case 'ArrowDown':  next = idx + cols;  break;
                    case 'Home':       next = idx - (idx % cols); break;
                    case 'End':        next = idx + (cols - 1 - (idx % cols)); break;
                    default: return;
                }
                e.preventDefault();
                if (cells[next]) cells[next].focus();
            });
        }

        if (clearBtn) {
            clearBtn.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                if (range) setRange(null, null);
                else setSelected(null);
            });
        }

        if (input) {
            input.addEventListener('input', () => {
                updateClear();
                if (range) return; // Bare-minimum: don't parse typed ranges.
                const d = parseISO(input.value);
                if (d) {
                    state.selected = d;
                    state.cursor = new Date(d.getFullYear(), d.getMonth(), 1);
                }
            });
        }
    };

    const boot = (root = document) => {
        for (const el of root.querySelectorAll('[data-datepicker]')) init(el);
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => boot(), { once: true });
    } else {
        boot();
    }

    const inner = document.getElementById('content-inner');
    if (inner) {
        const observer = new MutationObserver(() => boot(inner));
        observer.observe(inner, { childList: true, subtree: true });
    }
})();

